// Parse la réponse JSON de Claude
const claudeResponse = $json.output || $json.response || '{}';
let emailData;

try {
  let cleanJson = claudeResponse;
  if (typeof claudeResponse === 'string') {
    cleanJson = claudeResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  }
  emailData = typeof cleanJson === 'string' ? JSON.parse(cleanJson) : cleanJson;
} catch (e) {
  // Fallback en cas d'erreur
  const prospect = $('Split In Batches').item.json;
  emailData = {
    subject: 'Optimisation digitale pour ' + (prospect.company || 'votre entreprise'),
    body: 'Bonjour ' + (prospect.first_name || 'Madame, Monsieur') + ',\n\nJe vous contacte car LX Studio aide les PME en Suisse romande à automatiser leurs processus.\n\nSeriez-vous ouvert à un bref échange ?\n\nCordialement,\nLX Studio',
    preview_text: 'Automatisation pour PME Suisse romande',
    personalization_elements: []
  };
}

const prospect = $('Split In Batches').item.json;

return {
  json: {
    ...emailData,
    contact_id: prospect.id,
    contact_email: prospect.email,
    contact_first_name: prospect.first_name
  }
};

// Génère un hash pour l'opt-out
const crypto = require('crypto');
const contactEmail = $json.contact_email;

const unsubscribeHash = crypto
  .createHash('sha256')
  .update(`${contactEmail}:${process.env.HASH_SECRET || 'lx-studio-secret'}`)
  .digest('hex')
  .substring(0, 16);

const unsubscribeUrl = `${process.env.BASE_URL_N8N}/webhook/lx/unsubscribe?email=${encodeURIComponent(contactEmail)}&hash=${unsubscribeHash}`;

// Ajoute le footer avec opt-out
const fullBody = $json.body + '\n\n---\n' +
  'Tanguy Lachat\n' +
  'LX Studio - Agence Web & Automatisation\n' +
  'Email: contact@lxstudio.ch | Web: lxstudio.ch\n' +
  '📅 Prendre rendez-vous: ' + (process.env.CALENDLY_LINK || '') + '\n\n' +
  'Vous recevez cet email car votre profil correspond à notre cible.\n' +
  'Se désabonner: ' + unsubscribeUrl;

return {
  json: {
    ...$json,
    body_with_footer: fullBody,
    unsubscribe_url: unsubscribeUrl,
    unsubscribe_hash: unsubscribeHash
  }
};

